import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

export default function LudoMatchBoard() {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [diceValue, setDiceValue] = useState(null);

  const stompClientRef = useRef(null);
  const pollingRef = useRef(null);
  const timeoutRef = useRef(null);

  const ALLOWED_FEES = [13, 23, 50];

  // আগের ম্যাচ চেক
  useEffect(() => {
    const checkExistingMatch = async () => {
      const token = localStorage.getItem("authToken");
      try {
        const res = await axios.get("http://localhost:8080/api/match/status", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.data?.gameId) {
          setGame(res.data);
          setStatus("⚠️ আগের ম্যাচ পাওয়া গেছে, যুক্ত হচ্ছি...");
        }
      } catch {
        console.warn("❗ আগের ম্যাচ চেক ব্যর্থ");
      }
    };
    checkExistingMatch();
  }, []);

  // WebSocket কানেকশন
  useEffect(() => {
    if (!game?.gameId) return;

    const token = localStorage.getItem("authToken");
    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      debug: () => {},
      onConnect: () => {
        client.subscribe(`/topic/match/${game.player1}`, (msg) => handleMatchUpdate(msg));
        client.subscribe(`/topic/match/${game.player2}`, (msg) => handleMatchUpdate(msg));
        client.subscribe(`/topic/game/${game.gameId}`, (msg) => handleGameUpdate(msg));
      },
    });
    client.activate();
    stompClientRef.current = client;

    return () => {
      if (client) client.deactivate();
    };
  }, [game?.gameId]);

  const handleMatchUpdate = (message) => {
    const data = JSON.parse(message.body);
    setGame((prev) => ({ ...prev, ...data }));

    if (data.status === "CANCELLED") {
      setStatus("❌ ম্যাচ ক্যানসেল হয়েছে");
      setGame(null);
    } else if (data.player1 && data.player2) {
      setStatus("🎮 গেম শুরু");
      const myGameId = localStorage.getItem("myGameId");
      if (myGameId === data.player1) setPlayerId(1);
      if (myGameId === data.player2) setPlayerId(2);
    }
  };

  const handleGameUpdate = (message) => {
    const state = JSON.parse(message.body);
    console.log("গেম স্টেট:", state);
  };

  // ম্যাচ রিকোয়েস্ট
  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(entryFee)) {
      setStatus("❌ ভুল এন্ট্রি ফি");
      return;
    }
    setLoading(true);
    setStatus("🔍 প্রতিপক্ষ খুঁজছি...");
    const token = localStorage.getItem("authToken");
    try {
      await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      pollingRef.current = setInterval(async () => {
        const res = await axios.get("http://localhost:8080/api/match/status", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.data?.gameId) {
          clearInterval(pollingRef.current);
          clearTimeout(timeoutRef.current);
          setGame(res.data);
          setStatus("🎉 প্রতিপক্ষ পাওয়া গেছে!");
        }
      }, 3000);

      timeoutRef.current = setTimeout(() => {
        clearInterval(pollingRef.current);
        setStatus("⏳ সময় শেষ, আবার চেষ্টা করুন");
        setLoading(false);
      }, 30 * 60 * 1000);
    } catch (err) {
      setStatus("⚠️ সার্ভার সমস্যা");
    } finally {
      setLoading(false);
    }
  };

  // ডাইস রোল
  const rollDice = async () => {
    if (!game?.gameId) return;
    const token = localStorage.getItem("authToken");
    const roll = Math.floor(Math.random() * 6) + 1;
    setDiceValue(roll);
    await axios.post(
      `http://localhost:8080/api/match/rollDice/${game.gameId}`,
      {},
      { headers: { Authorization: `Bearer ${token}` } }
    );
  };

  return (
    <div className="max-w-2xl mx-auto mt-8 p-6 bg-white rounded shadow">
      {!game ? (
        <>
          <h2 className="text-xl font-bold mb-4">🎲 লুডু ম্যাচ শুরু</h2>
          <select
            value={entryFee}
            onChange={(e) => setEntryFee(Number(e.target.value))}
            className="border p-2 rounded mb-4 w-full"
          >
            {ALLOWED_FEES.map((fee) => (
              <option key={fee} value={fee}>
                ৳ {fee}
              </option>
            ))}
          </select>
          <button
            onClick={handleMatchRequest}
            className="bg-indigo-600 text-white px-4 py-2 rounded w-full"
            disabled={loading}
          >
            {loading ? "⏳ খোঁজা হচ্ছে..." : "🔍 প্রতিপক্ষ খুঁজুন"}
          </button>
          {status && <p className="mt-3 text-gray-700">{status}</p>}
        </>
      ) : (
        <>
          <h2 className="text-xl font-bold mb-2">গেম আইডি: {game.gameId}</h2>
          <p>আপনি প্লেয়ার {playerId}</p>
          <p className="mt-2">{status}</p>
          <div className="mt-6">
            <button
              onClick={rollDice}
              className="bg-green-600 text-white px-4 py-2 rounded"
            >
              🎲 ডাইস চালান
            </button>
            {diceValue && <p className="mt-3">আপনার ডাইস: {diceValue}</p>}
          </div>
        </>
      )}
    </div>
  );
}
